import { z } from 'zod';
import { getVariables, replaceVariables } from '@types/function/variables';
import { getLastMessageId } from '@types/function/util';
import { getChatMessages, setChatMessages } from '@types/function/chat_message';
import { eventOn, getButtonEvent } from '@types/iframe/event';
import { tavern_events } from '@types/iframe/event';
import { getScriptId, replaceScriptButtons } from '@types/iframe/script';
import { klona } from 'klona';
import toastr from 'toastr';
import './style.scss';

// ==========================================
// 设置定义
// ==========================================

const SettingsSchema = z.object({
  enabled: z.boolean().default(false),
  preserveZeroFloor: z.boolean().default(true),
  loadCount: z.number().int().min(1).default(20),
});

type Settings = z.infer<typeof SettingsSchema>;

function getSettings(): Settings {
  const stored = getVariables({ type: 'script', script_id: getScriptId() });
  return SettingsSchema.parse(stored);
}

function saveSettings(settings: Settings): void {
  replaceVariables(klona(settings), { type: 'script', script_id: getScriptId() });
}

// ==========================================
// 核心功能
// ==========================================

// 计算需要隐藏的楼层 message_id 列表
function getMessagesToHide(): number[] {
  const settings = getSettings();
  if (!settings.enabled) return [];

  const lastId = getLastMessageId();
  if (lastId < 0) return [];

  const messages = getChatMessages(`0-${lastId}`);

  // 计算从哪个索引开始隐藏
  let startIndex: number;
  if (settings.preserveZeroFloor) {
    // 保留第零层 + 最新 X 层（即隐藏从 X 开始）
    startIndex = settings.loadCount;
  } else {
    // 不保留第零层，仅最新 X 层（即隐藏从 X-1 开始）
    startIndex = settings.loadCount - 1;
  }

  return messages
    .filter((_, index) => index >= startIndex)
    .filter(msg => !msg.is_hidden)
    .map(msg => msg.message_id);
}

// 计算需要取消隐藏的楼层 message_id 列表
function getMessagesToUnhide(): number[] {
  const lastId = getLastMessageId();
  if (lastId < 0) return [];

  const messages = getChatMessages(`0-${lastId}`, { hide_state: 'hidden' });
  return messages
    .filter(msg => msg.is_hidden)
    .map(msg => msg.message_id);
}

// 应用消息限制（隐藏超出范围的楼层）
async function applyMessageLimit(): Promise<void> {
  const settings = getSettings();
  if (!settings.enabled) {
    toastr.warning('请先启用消息限制功能');
    return;
  }

  const messagesToHide = getMessagesToHide();
  if (messagesToHide.length === 0) {
    toastr.info('当前没有需要隐藏的楼层');
    return;
  }

  await setChatMessages(
    messagesToHide.map(message_id => ({ message_id, is_hidden: true })),
    { refresh: 'none' }
  );
  toastr.success(`已隐藏 ${messagesToHide.length} 个楼层`);
}

// 取消所有隐藏
async function unhideAllMessages(): Promise<void> {
  const messagesToUnhide = getMessagesToUnhide();
  if (messagesToUnhide.length === 0) {
    toastr.info('当前没有需要取消隐藏的楼层');
    return;
  }

  await setChatMessages(
    messagesToUnhide.map(message_id => ({ message_id, is_hidden: false })),
    { refresh: 'all' }
  );
  toastr.success(`已取消隐藏 ${messagesToUnhide.length} 个楼层`);
}

// ==========================================
// UI 面板
// ==========================================

// 切换设置面板显示
function toggleSettingsPanel(): void {
  let $panel = $('#limit-messages-panel');
  if ($panel.length > 0) {
    $panel.remove();
  } else {
    $panel = createSettingsPanel();
    $('body').append($panel);
    bindSettingsPanelEvents();
  }
}

// 创建设置面板
function createSettingsPanel(): JQuery<HTMLElement> {
  const settings = getSettings();
  const lastId = getLastMessageId();
  const totalCount = lastId + 1;
  const effectiveCount = settings.enabled
    ? Math.min(settings.loadCount + (settings.preserveZeroFloor ? 1 : 0), totalCount)
    : totalCount;

  const html = `
    <div id="limit-messages-panel" class="limit-messages-panel">
      <div class="limit-messages-header">
        <span class="limit-messages-title">消息限制设置</span>
        <button class="limit-messages-close" id="limit-messages-close-btn">&times;</button>
      </div>

      <div class="limit-messages-body">
        <div class="limit-messages-status">
          <i class="fa-solid fa-layer-group"></i>
          <span>当前共 <strong>${totalCount}</strong> 楼，将保留 <strong>${effectiveCount}</strong> 楼</span>
        </div>

        <div class="limit-messages-setting-item">
          <div class="limit-messages-setting-label">
            <span>启用消息限制</span>
            <small>开启后会自动隐藏超出范围的楼层</small>
          </div>
          <label class="limit-messages-switch">
            <input type="checkbox" id="lm-enabled" ${settings.enabled ? 'checked' : ''}>
            <span class="limit-messages-slider"></span>
          </label>
        </div>

        <div class="limit-messages-setting-item">
          <div class="limit-messages-setting-label">
            <span>保留第零层</span>
            <small>勾选：显示 0~X 楼（X+1 层）；不勾选：显示 1~X 楼（X 层）</small>
          </div>
          <label class="limit-messages-switch">
            <input type="checkbox" id="lm-preserve-zero" ${settings.preserveZeroFloor ? 'checked' : ''}>
            <span class="limit-messages-slider"></span>
          </label>
        </div>

        <div class="limit-messages-setting-item">
          <div class="limit-messages-setting-label">
            <span>加载最新消息数量 (X)</span>
            <small>保留的最新楼层数量，最少 1</small>
          </div>
          <input type="number" id="lm-load-count" class="limit-messages-number-input"
            value="${settings.loadCount}" min="1" max="1000">
        </div>
      </div>

      <div class="limit-messages-footer">
        <button class="limit-messages-btn limit-messages-btn-primary" id="lm-apply-btn">
          <i class="fa-solid fa-check"></i> 应用设置
        </button>
        <button class="limit-messages-btn limit-messages-btn-secondary" id="lm-unhide-btn">
          <i class="fa-solid fa-eye"></i> 取消全部隐藏
        </button>
      </div>
    </div>
  `;

  return $(html);
}

// 绑定设置面板事件
function bindSettingsPanelEvents(): void {
  // 关闭按钮
  $('#limit-messages-close-btn').on('click', () => {
    $('#limit-messages-panel').remove();
  });

  // 点击遮罩关闭
  $('#limit-messages-panel').on('click', function (e) {
    if (e.target === this) {
      $(this).remove();
    }
  });

  // 启用开关
  $('#lm-enabled').on('change', function () {
    const settings = getSettings();
    settings.enabled = $(this).is(':checked');
    saveSettings(settings);
  });

  // 保留第零层开关
  $('#lm-preserve-zero').on('change', function () {
    const settings = getSettings();
    settings.preserveZeroFloor = $(this).is(':checked');
    saveSettings(settings);
  });

  // 加载数量输入
  $('#lm-load-count').on('change', function () {
    const value = parseInt($(this).val() as string, 10);
    if (!isNaN(value) && value >= 1) {
      const settings = getSettings();
      settings.loadCount = value;
      saveSettings(settings);
    } else {
      toastr.warning('加载数量必须为大于 0 的整数');
      $(this).val(getSettings().loadCount);
    }
  });

  // 应用按钮
  $('#lm-apply-btn').on('click', async () => {
    await applyMessageLimit();
    // 刷新面板显示
    $('#limit-messages-panel').remove();
    toggleSettingsPanel();
  });

  // 取消隐藏按钮
  $('#lm-unhide-btn').on('click', async () => {
    await unhideAllMessages();
    // 刷新面板显示
    $('#limit-messages-panel').remove();
    toggleSettingsPanel();
  });
}

// ==========================================
// 按钮注册
// ==========================================

function registerButtons(): void {
  replaceScriptButtons([
    { name: '限制消息设置', visible: true },
    { name: '应用消息限制', visible: true },
    { name: '取消全部隐藏', visible: true },
  ]);

  eventOn(getButtonEvent('限制消息设置'), toggleSettingsPanel);
  eventOn(getButtonEvent('应用消息限制'), applyMessageLimit);
  eventOn(getButtonEvent('取消全部隐藏'), unhideAllMessages);
}

// ==========================================
// 自动应用限制（消息生成后）
// ==========================================

function setupAutoApply(): void {
  eventOn(tavern_events.MESSAGE_RECEIVED, async () => {
    const settings = getSettings();
    if (settings.enabled) {
      await applyMessageLimit();
    }
  });

  eventOn(tavern_events.CHAT_CHANGED, async () => {
    const settings = getSettings();
    if (settings.enabled) {
      await applyMessageLimit();
    }
  });
}

// ==========================================
// 初始化
// ==========================================

$(() => {
  registerButtons();
  setupAutoApply();
  toastr.success('消息限制脚本已加载');
});